# frozen_string_literal: true

module Whatsapp
  # Drafts a translation of a template's text with Claude (Anthropic Messages API). Only the
  # translatable strings are sent; the result is merged back into a copy of the English components,
  # so structure, URLs, examples and variables are never generated by the model. A person reviews
  # every draft in the support dashboard before it can be submitted.
  class TemplateTranslator
    API_URL = "https://api.anthropic.com/v1/messages"
    API_VERSION = "2023-06-01"
    DEFAULT_MODEL = "claude-sonnet-5-5"
    TIMEOUT = 60

    class Error < StandardError; end

    STYLE = {
      "ur" => "Urdu in Urdu script (Nastaliq), not Roman Urdu. Polite, simple everyday Pakistani Urdu; " \
              "keep common English e-commerce words (order, COD, delivery) where Pakistanis normally use them.",
      "ar" => "Arabic. Simple Modern Standard Arabic that reads naturally to shoppers in Egypt and the Gulf; " \
              "polite and short."
    }.freeze

    def initialize(api_key: ENV["ANTHROPIC_API_KEY"], model: ENV["ANTHROPIC_TRANSLATION_MODEL"].presence || DEFAULT_MODEL)
      @api_key = api_key
      @model = model
    end

    # => translated components (same structure as `source_components`)
    def translate(source_components, language)
      raise Error, "ANTHROPIC_API_KEY is not set" if @api_key.blank?

      strings = TemplateComponents.translatable(source_components)
      raise Error, "Nothing to translate in this template" if strings.empty?

      translated = request(strings, language)
      if (bad = edge_variable_ids(translated)).any?
        # One redraft with the problem spelled out; anything left is flagged by the validator on review.
        retried = request(strings, language, feedback: edge_feedback(translated, bad))
        translated = merge_fixed(translated, retried, bad)
      end
      TemplateComponents.apply(source_components, translated)
    end

    private

    # Ids of translated body texts that begin or end with a variable (Meta rejects those).
    def edge_variable_ids(translated)
      translated.select { |t| t["id"].to_s == "body" && TemplateComponents.edge_variable?(t["text"]) }.map { |t| t["id"].to_s }
    end

    def edge_feedback(translated, ids)
      texts = translated.select { |t| ids.include?(t["id"].to_s) }.map { |t| "#{t['id']}: #{t['text']}" }.join("\n")
      "Your previous translation of these texts started or ended with a variable, which WhatsApp rejects:\n" \
        "#{texts}\nRephrase so the first and last words are real words, never {{n}} (punctuation after {{n}} does not count)."
    end

    def merge_fixed(translated, retried, ids)
      fixed = retried.to_h { |t| [t["id"].to_s, t] }
      translated.map do |t|
        candidate = fixed[t["id"].to_s]
        ids.include?(t["id"].to_s) && candidate && !TemplateComponents.edge_variable?(candidate["text"]) ? candidate : t
      end
    end

    def request(strings, language, feedback: nil)
      style = STYLE[language] || WhatsappTemplateTranslation.language_name(language)
      prompt = <<~PROMPT
        Translate these WhatsApp order-notification texts from English into #{style}

        Rules:
        - Keep every variable such as {{1}} or {{2}} exactly as written, the same number of times. Move it
          only if the target grammar needs it; never translate, renumber or drop it.
        - Keep URLs, numbers, emoji and brand names unchanged.
        - Keep it transactional (order updates), not promotional, so WhatsApp keeps it in the Utility category.
        - Button labels must stay under 25 characters.
        - The body must never start or end with a variable: its first and last words (in reading order,
          so the rightmost word for right-to-left scripts) must be real words. Punctuation, spaces or
          emoji after a variable do NOT count — "فريق {{4}}." still ends with a variable. WhatsApp
          rejects the template otherwise (Arabic sign-off: "فريق {{4}} في خدمتك."). Rephrase if the natural word order would put {{1}} first,
          e.g. Urdu "آپ کے {{1}} پر دیے گئے آرڈر کا شکریہ۔" rather than "{{1}} پر آپ کے آرڈر کا شکریہ۔".

        #{feedback}

        Check every rule before you answer. Return only the final JSON: one array of
        {"id": ..., "text": ...} with the same ids — no drafts, corrections or commentary.

        #{JSON.pretty_generate(strings)}
      PROMPT

      response = HTTParty.post(
        API_URL,
        headers: { "x-api-key" => @api_key, "anthropic-version" => API_VERSION, "content-type" => "application/json" },
        body: { model: @model, max_tokens: 2000, messages: [{ role: "user", content: prompt }] }.to_json,
        timeout: TIMEOUT
      )
      raise Error, "Translation request failed (HTTP #{response.code}): #{response.body.to_s.first(300)}" unless response.success?

      text = Array(response.parsed_response["content"]).filter_map { |part| part["text"] if part["type"] == "text" }.join
      parse(text, strings)
    end

    # The model sometimes self-corrects mid-reply ("Wait — ... here is the corrected version:") and
    # returns more than one list, so take the last complete JSON array that has every id.
    def parse(text, strings)
      ids = strings.map { |s| s["id"] }
      lists = json_arrays(text)
      raise Error, "Translation response was not JSON" if lists.empty?

      list = lists.reverse.find { |l| complete?(l, ids) } || lists.last
      result = list.select { |t| t.is_a?(Hash) && ids.include?(t["id"].to_s) && t["text"].is_a?(String) }
      missing = ids - result.map { |t| t["id"].to_s }
      raise Error, "Translation is missing: #{missing.join(', ')}" if missing.any?

      result
    end

    def complete?(list, ids)
      (ids - list.filter_map { |t| t["id"].to_s if t.is_a?(Hash) && t["text"].is_a?(String) }).empty?
    end

    # Every top-level [...] in the text that parses as a JSON array. Brackets inside JSON strings
    # are skipped so "[" in translated text doesn't break the scan.
    def json_arrays(text)
      found = []
      i = 0
      while (start = text.index("[", i))
        depth = 0
        in_string = false
        escaped = false
        stop = nil
        (start...text.length).each do |j|
          ch = text[j]
          if in_string
            if escaped then escaped = false
            elsif ch == "\\" then escaped = true
            elsif ch == '"' then in_string = false
            end
            next
          end
          case ch
          when '"' then in_string = true
          when "[" then depth += 1
          when "]"
            depth -= 1
            if depth.zero?
              stop = j
              break
            end
          end
        end
        break unless stop

        begin
          parsed = JSON.parse(text[start..stop])
          found << parsed if parsed.is_a?(Array)
          i = stop + 1
        rescue JSON::ParserError
          i = start + 1
        end
      end
      found
    end
  end
end
